fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());for name in ["mother","island","clean","nested","ring","partial","3d","flipped"]{let mut scene=ingetrazo_formats::igz::load_igz(&dir.join(format!("{name}-source.igz"))).unwrap();let(mesh,removed)=ingetrazo_core::heal::heal_faces(&scene.mesh,0.5,if name=="island"{Some(false)}else{None}).unwrap();scene.mesh=mesh;ingetrazo_formats::igz::save_igz(&scene,&dir.join(format!("{name}-result.igz"))).unwrap();std::fs::write(dir.join(format!("{name}-removed.json")),serde_json::to_vec(&removed).unwrap()).unwrap();}}
